import{_ as e,o,c as p,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Month 2021: RBD Update","description":"","frontmatter":{"title":"Ceph Month 2021: RBD Update","date":"2021-06-14T00:00:00.000Z","updated":"2021-06-15T00:00:00.000Z","tags":["Ceph","RBD","分布式存储","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_RBD_Update.md","filePath":"posts/2021/Ceph_Month_2021_-_RBD_Update.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Month_2021_-_RBD_Update.md"};function s(l,t,_,a,r,d){return o(),p("div",null,[...t[0]||(t[0]=[n("<p>Ceph Month 2021会议中，RBD团队技术负责人Ilya介绍了RBD的更新情况，包括以下关键点：</p><ol><li><p><strong>即时导入（Instant Import）</strong>：支持从外部数据源导入图像，包括本地和远程文件，以及兼容Amazon S3的对象存储中的文件。支持的数据源格式包括raw、qcow2等，但不支持压缩、加密等高级功能。</p></li><li><p><strong>内置加密（Built-in Encryption）</strong>：引入基于LUKS的加密，使用AES加密算法，支持LUKS1和LUKS2格式。当前仅支持非克隆图像的加密格式化。</p></li><li><p><strong>性能改进</strong>：通过重写librbd I/O路径，改进了小I/O性能，提升了I/O操作的效率。引入了客户端持久写回缓存，改善了缓存管理和数据一致性。</p></li><li><p><strong>快照QS钩子</strong>：新增RPC消息，支持协调快照创建，特别是在集群级别的镜像快照中。</p></li><li><p><strong>内核客户端支持</strong>：内核5.11支持Ceph Messenger 2.1协议，改进了客户端与集群的通信。支持副本读取和压缩操作，优化了跨数据中心的性能。</p></li><li><p><strong>Windows支持</strong>：实现了Windows下的librbd和librados支持，通过wnbd驱动提供类似Linux的块设备接口。</p></li></ol><p>会议决定继续完善和扩展RBD的功能，特别是在加密、性能优化和跨平台支持方面。后续行动计划包括：</p><ul><li>完成加密格式化克隆和持久写回缓存的改进。</li><li>扩展崩溃恢复测试，优化缓存状态的可观测性和解释性。</li><li>增强 RBD 的监控和报警功能，特别是在镜像和快照管理方面。</li><li>探索和实施NVMe-oF目标网关，提升性能和可扩展性。</li><li>改进QEMU块驱动，支持写零操作和加密格式化图像的加载。</li></ul>",4)])])}const g=e(i,[["render",s]]);export{c as __pageData,g as default};
